<template><AccountLayout bare><main class="po-page" :aria-busy="busy">
<header class="po-header"><div class="po-heading"><ClipboardList :size="30"/><div><h1>Sales Order</h1><p>Customer Accepted Orders</p></div></div><div v-if="view==='list'" class="po-header-search"><Search/><input v-model="search" placeholder="Search order no., customer or customer PO..."></div><div class="po-actions"><button v-if="view==='list'" class="po-btn primary" @click="startNew"><Plus/> New Sales Order</button><button v-else class="po-btn" @click="back"><ArrowLeft/> Back to list</button><span v-if="view==='detail'" class="po-pill" :class="slug(form.status)">{{ form.status }}</span></div></header>
<div v-if="error" class="po-alert error">{{ error }}</div><div v-if="notice" class="po-alert success">{{ notice }}</div>
<template v-if="view==='list'"><section class="po-metrics"><article v-for="card in metrics" :key="card.label" :class="card.tone"><component :is="card.icon" :size="30"/><div><h2>{{ card.label }}</h2><strong>{{ card.rows.length }} <small>Orders</small></strong><b>{{ money(card.rows.reduce((s,x)=>s+Number(x.total),0)) }} CAD</b></div></article></section><section class="po-list"><header class="po-section-head"><h2>Sales Order List</h2><div class="po-actions"><button class="po-btn primary" @click="startNew"><Plus/> New Sales Order</button><button class="po-btn green" @click="exportExcel"><Download/> Export</button></div></header><div class="po-table-scroll"><table class="po-list-table"><thead><tr><th>No.</th><th>Sales Order No.</th><th>Order Date</th><th>Valid Until</th><th>Customer</th><th>Customer PO</th><th>Salesperson</th><th>Total</th><th>Status</th><th>Created By</th><th>View</th></tr></thead><tbody><tr v-for="(row,index) in filtered" :key="row.id"><td>{{ index+1 }}</td><td><button class="po-link" @click="openOrder(row)">{{ row.order_no }}</button></td><td>{{ dateLabel(row.order_date) }}</td><td>{{ dateLabel(row.valid_until) }}</td><td>{{ row.customer_details?.name }}</td><td>{{ row.customer_po_no||'-' }}</td><td>{{ row.salesperson||'-' }}</td><td class="po-number">{{ money(row.total) }} {{ row.currency_code }}</td><td><span class="po-pill" :class="slug(row.status)">{{ row.status }}</span></td><td>{{ row.creator?.name||'-' }}</td><td><button class="po-btn compact" @click="openOrder(row)"><Eye/> View</button></td></tr><tr v-if="!filtered.length"><td colspan="11" class="po-empty">No sales orders found.</td></tr></tbody></table></div><div class="po-action-bar"><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn green" @click="exportExcel"><FileSpreadsheet/> Export Excel</button></div></section></template>
<div v-else class="po-workspace"><section class="po-document"><header class="po-document-head"><div class="po-heading"><ClipboardList/><h2>Sales Order <small v-if="form.status==='Confirmed'">(Customer Accepted)</small></h2></div><div class="po-actions"><b>{{ form.order_no||'New order' }}</b><span class="po-pill" :class="slug(form.status)">{{ form.status }}</span><button class="po-icon" title="Print" @click="printPage"><Printer/></button><button class="po-icon" title="Email" @click="emailOrder"><Mail/></button></div></header><div class="po-document-body">
<div class="po-details-grid"><section><h3>1. Customer Information</h3><div v-if="editing" class="po-field"><label>Customer</label><i>:</i><select v-model="form.customer_id" @change="applyCustomer"><option :value="null" disabled>Select customer</option><option v-for="x in customers" :key="x.id" :value="x.id">{{ x.name }}</option></select></div><Field label="Customer ID" :model-value="customer.customer_no"/><Field label="Customer Name" :model-value="customer.name"/><Field label="Contact Person" :model-value="customer.contact_person"/><Field label="Phone" :model-value="customer.phone"/><Field label="Email" :model-value="customer.email"/><Field label="Address" :model-value="customer.address" multiline/><Field label="Customer Balance" :model-value="money(customer.balance)+' '+form.currency_code"/><Field label="Credit Limit" :model-value="money(customer.credit_limit)+' '+form.currency_code"/></section>
<section><h3>2. Order Information</h3><Field label="Sales Order No." v-model="form.order_no" :editable="editing"/><Field label="Order Date" v-model="form.order_date" :editable="editing" type="date" :display-value="dateLabel(form.order_date)"/><Field label="Valid Until" v-model="form.valid_until" :editable="editing" type="date" :display-value="dateLabel(form.valid_until)"/><div v-if="editing" class="po-field"><label>Estimate / Quote</label><i>:</i><select v-model="form.estimation_id" @change="applyEstimate"><option :value="null">No quote</option><option v-for="x in customerEstimates" :key="x.id" :value="x.id">{{ x.estimation_no }}</option></select></div><Field v-else label="Quote No." :model-value="form.estimation?.estimation_no"/><Field label="Customer PO No." v-model="form.customer_po_no" :editable="editing"/><Field label="Salesperson" v-model="form.salesperson" :editable="editing"/><Field label="Sales Department" v-model="form.department" :editable="editing"/><Field label="Currency" v-model="form.currency_code" :editable="editing" :options="currencies"/><Field label="Exchange Rate" v-model="form.exchange_rate" :editable="editing" type="number"/><Field label="Price List" v-model="form.price_list" :editable="editing"/><Field label="Sales Channel" v-model="form.sales_channel" :editable="editing" :options="channels"/></section>
<section><h3>3. Delivery &amp; Other Details</h3><Field label="Delivery Location" v-model="form.delivery_location" :editable="editing"/><Field label="Shipping Method" v-model="form.shipping_method" :editable="editing" :options="shippingMethods"/><Field label="Expected Delivery" v-model="form.expected_delivery_date" :editable="editing" type="date" :display-value="dateLabel(form.expected_delivery_date)"/><Field label="Shipping Terms" v-model="form.shipping_terms" :editable="editing"/><Field label="Payment Terms" v-model="form.payment_terms" :editable="editing"/><Field label="Reference" v-model="form.reference" :editable="editing"/><Field label="Remarks / Memo" v-model="form.notes" :editable="editing" multiline/></section></div>
<section class="po-items"><div class="po-section-head"><h3>4. Item / Service Details</h3><button v-if="editing" class="po-btn compact primary" @click="addItem"><Plus/> Add New Line</button></div><div class="po-table-scroll"><table><thead><tr><th>#</th><th>Item / Service</th><th>Description</th><th>UOM</th><th>Qty</th><th>Unit Price</th><th>Discount (%)</th><th>Tax (%)</th><th>Amount</th><th v-if="editing">Action</th></tr></thead><tbody><tr v-for="(item,index) in form.items" :key="index"><td>{{ index+1 }}</td><td><input v-if="editing" v-model="item.name"><span v-else>{{ item.name }}</span></td><td><input v-if="editing" v-model="item.description"><span v-else>{{ item.description }}</span></td><td><input v-if="editing" v-model="item.uom"><span v-else>{{ item.uom }}</span></td><td><input v-if="editing" v-model.number="item.quantity" type="number" min=".01" step=".01"><span v-else>{{ money(item.quantity) }}</span></td><td><input v-if="editing" v-model.number="item.unit_price" type="number" min="0" step=".01"><span v-else>{{ money(item.unit_price) }}</span></td><td><input v-if="editing" v-model.number="item.discount" type="number" min="0" max="100"><span v-else>{{ money(item.discount) }}</span></td><td><input v-if="editing" v-model.number="item.tax_rate" type="number" min="0" max="100"><span v-else>{{ money(item.tax_rate) }}%</span></td><td>{{ money(lineTotal(item)) }}</td><td v-if="editing"><button class="po-icon danger" @click="form.items.splice(index,1)"><Trash2/></button></td></tr><tr v-if="!form.items.length"><td :colspan="editing?10:9" class="po-empty">No items added.</td></tr></tbody></table></div></section>
<div class="po-bottom-grid"><section><h3>5. Terms &amp; Conditions</h3><textarea v-if="editing" v-model="form.terms" rows="7"/><p v-else class="po-terms">{{ form.terms||'-' }}</p><Field label="Created By" :model-value="form.creator?.name"/><Field label="Created Date" :model-value="dateTimeLabel(form.created_at)"/></section><section><h3>6. Tax Summary</h3><Field label="Taxable Amount" :model-value="money(subtotal-discount)"/><Field label="Discount Amount" :model-value="money(discount)"/><Field label="Total Tax" :model-value="money(tax)"/></section><section class="po-totals"><Field label="Sub Total" :model-value="money(subtotal)"/><Field label="Discount Amount" :model-value="money(discount)"/><Field label="Taxable Amount" :model-value="money(subtotal-discount)"/><Field label="Total Tax" :model-value="money(tax)"/><div><span>Grand Total ({{ form.currency_code }})</span><strong>{{ money(total) }}</strong></div></section></div><section v-if="form.attachments.length" class="po-attachments"><h3>Attachments</h3><button v-for="x in form.attachments" :key="x.id" class="po-btn compact" @click="downloadAttachment(x)"><Paperclip/> {{ x.name }}</button></section></div>
<footer class="po-document-footer"><div class="po-actions"><button class="po-btn" @click="startNew"><Plus/> New</button><button class="po-btn" :disabled="editing||['Confirmed','Completed'].includes(form.status)" @click="editing=true"><Pencil/> Edit</button><button class="po-btn danger" :disabled="!form.id||['Confirmed','Completed'].includes(form.status)" @click="deleteOrder"><Trash2/> Delete</button><button class="po-btn primary" :disabled="!editing" @click="saveOrder"><Save/> Save</button><button v-if="editing" class="po-btn" @click="cancel"><X/> Cancel</button><button class="po-btn" @click="savePdf"><FileDown/> Save PDF</button><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn" @click="emailOrder"><Mail/> Email</button><button class="po-btn" :disabled="!form.id" @click="fileInput.click()"><Paperclip/> Attach File</button><input ref="fileInput" class="po-hidden" type="file" @change="upload"><button class="po-btn" :disabled="!form.id" @click="modal='audit'"><History/> Audit Log</button><button class="po-btn green" :disabled="!canConfirm" @click="workflow('confirm')"><Check/> Confirm</button><button class="po-btn primary" :disabled="!canSubmit" @click="workflow('submit')"><Send/> Send for Approval</button></div></footer></section>
<aside class="po-sidebar"><section><h3>Transaction Tracker</h3><div class="po-table-scroll"><table class="po-tracker"><thead><tr><th>Doc. Type</th><th>No.</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-if="form.estimation"><td>Sales Estimate / Quote</td><td>{{ form.estimation.estimation_no }}</td><td>{{ dateLabel(form.estimation.issue_date) }}</td><td>{{ money(total) }}</td><td>Converted</td></tr><tr><td>Sales Order</td><td>{{ form.order_no||'-' }}</td><td>{{ dateLabel(form.order_date) }}</td><td>{{ money(total) }}</td><td>{{ form.status }}</td></tr><tr><td>Sales Invoice</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Sales Return</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Credit Note</td><td>-</td><td>-</td><td>-</td><td>-</td></tr></tbody></table></div></section><section><h3>Quick Reports</h3><button v-for="x in reports" :key="x" class="po-report-link"><span>{{ x }}</span><ChevronRight/></button></section><section><h3>8. Customer Summary</h3><Field label="Customer Balance" :model-value="money(customer.balance)+' '+form.currency_code"/><Field label="Credit Limit" :model-value="money(customer.credit_limit)+' '+form.currency_code"/><Field label="Available Credit" :model-value="money(availableCredit)+' '+form.currency_code"/></section></aside></div>
<div v-if="modal" class="po-modal-backdrop" @click.self="modal=''"> <section class="po-modal"><header><h2>Sales Order Audit Log</h2><button class="po-icon" @click="modal=''"><X/></button></header><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><tr v-for="x in form.activities" :key="x.id"><td>{{ dateTimeLabel(x.created_at) }}</td><td>{{ x.actor }}</td><td>{{ x.action }}</td><td>{{ details(x.changes) }}</td></tr></tbody></table></section></div>
</main></AccountLayout></template>
<script setup>
import{computed,onMounted,ref}from'vue';import{ClipboardList,Search,Plus,ArrowLeft,Download,Eye,Printer,Mail,FileSpreadsheet,Pencil,Trash2,Save,X,FileDown,Paperclip,History,Check,Send,ChevronRight,WalletCards,Clock,BadgeCheck,CircleX}from'lucide-vue-next';import AccountLayout from'../components/AccountLayout.vue';import Field from'../components/PurchaseOrderField.vue';import client from'../api/client';import{today,money,dateLabel,dateTimeLabel,roundMoney}from'../utils/purchaseOrders'
const rows=ref([]),customers=ref([]),estimates=ref([]),currencies=ref(['CAD','USD']),view=ref('list'),form=ref({}),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),fileInput=ref(null),search=ref('');const channels=['Direct','Online','Referral','Partner'],shippingMethods=['Our Truck','Courier','Customer Pickup','Third Party'],reports=['Sales Documents','Customer Payments','Unpaid Invoices','AR Aging Report','Customer Statement','Sales by Customer','Sales by Item','Sales by Salesperson'],blank=()=>({id:null,order_no:'',customer_id:null,estimation_id:null,order_date:today(),valid_until:'',customer_po_no:'',salesperson:'',department:'Sales',currency_code:'CAD',exchange_rate:1,price_list:'Standard Price List',sales_channel:'Direct',delivery_location:'',shipping_method:'Our Truck',expected_delivery_date:'',shipping_terms:'FOB Destination',payment_terms:'Net 15',reference:'',status:'Draft',customer_details:{},items:[],terms:'Prices are subject to change without prior notice. Payment is due within the agreed terms.',notes:'',activities:[],attachments:[],estimation:null})
const slug=x=>String(x||'').toLowerCase().replace(/\s+/g,'-'),customer=computed(()=>form.value.customer_details||{}),customerEstimates=computed(()=>estimates.value.filter(x=>Number(x.customer_id)===Number(form.value.customer_id))),filtered=computed(()=>rows.value.filter(x=>[x.order_no,x.customer_po_no,x.customer_details?.name].some(v=>String(v||'').toLowerCase().includes(search.value.toLowerCase())))),subtotal=computed(()=>roundMoney(form.value.items.reduce((s,x)=>s+Number(x.quantity||0)*Number(x.unit_price||0),0))),discount=computed(()=>roundMoney(form.value.items.reduce((s,x)=>s+Number(x.quantity||0)*Number(x.unit_price||0)*Number(x.discount||0)/100,0))),tax=computed(()=>roundMoney(form.value.items.reduce((s,x)=>s+(Number(x.quantity||0)*Number(x.unit_price||0)*(1-Number(x.discount||0)/100))*Number(x.tax_rate||0)/100,0))),total=computed(()=>roundMoney(subtotal.value-discount.value+tax.value)),availableCredit=computed(()=>Math.max(0,Number(customer.value.credit_limit||0)-Number(customer.value.balance||0)-total.value)),canSubmit=computed(()=>form.value.id&&!editing.value&&['Draft','Rejected'].includes(form.value.status)),canConfirm=computed(()=>form.value.id&&!editing.value&&['Draft','Pending Approval'].includes(form.value.status)),metrics=computed(()=>[{label:'Total Orders',rows:filtered.value,icon:WalletCards,tone:'blue'},{label:'Draft',rows:filtered.value.filter(x=>x.status==='Draft'),icon:Clock,tone:'amber'},{label:'Confirmed',rows:filtered.value.filter(x=>x.status==='Confirmed'),icon:BadgeCheck,tone:'green'},{label:'Rejected',rows:filtered.value.filter(x=>x.status==='Rejected'),icon:CircleX,tone:'red'}]);function lineTotal(x){const base=Number(x.quantity||0)*Number(x.unit_price||0)*(1-Number(x.discount||0)/100);return roundMoney(base+base*Number(x.tax_rate||0)/100)}const apiError=e=>Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||e.message
async function all(url){let p=1,last=1,out=[];do{const{data}=await client.get(url,{params:{per_page:100,page:p}}),b=data.data;out.push(...(b?.data||b||[]));last=b?.last_page||1;p++}while(p<=last);return out}async function load(){const[r,o,c]=await Promise.all([all('/sales-orders'),client.get('/sales-orders/options'),all('/currencies')]);rows.value=r;customers.value=o.data.data.customers;estimates.value=o.data.data.estimates;if(c.length)currencies.value=[...new Set(c.map(x=>x.currency_code))]}function normalize(x){const b=blank();return{...b,...x,customer_id:x.customer_id?Number(x.customer_id):null,estimation_id:x.estimation_id?Number(x.estimation_id):null,order_date:String(x.order_date||today()).slice(0,10),valid_until:String(x.valid_until||'').slice(0,10),expected_delivery_date:String(x.expected_delivery_date||'').slice(0,10),exchange_rate:Number(x.exchange_rate||1),customer_details:{...b.customer_details,...x.customer_details},items:(x.items||[]).map(i=>({...i})),activities:x.activities||[],attachments:x.attachments||[]}}
function startNew(){form.value=blank();editing.value=true;view.value='detail'}async function openOrder(x){busy.value=true;try{const{data}=await client.get('/sales-orders/'+x.id);form.value=normalize(data.data);editing.value=false;view.value='detail'}catch(e){error.value=apiError(e)}finally{busy.value=false}}function back(){view.value='list';editing.value=false}async function cancel(){form.value.id?await openOrder(form.value):back()}function applyCustomer(){const x=customers.value.find(x=>x.id===Number(form.value.customer_id));form.value.customer_details=x||{};form.value.payment_terms=x?.payment_terms||'Net 15';form.value.delivery_location=x?.address||'';form.value.estimation_id=null}function applyEstimate(){const x=estimates.value.find(x=>x.id===Number(form.value.estimation_id));if(!x)return;form.value.items=x.items.map(i=>({...i}));form.value.currency_code=x.currency_code;form.value.payment_terms=x.payment_terms||form.value.payment_terms;form.value.terms=x.terms||form.value.terms;form.value.notes=x.notes||form.value.notes}function addItem(){form.value.items.push({name:'',description:'',uom:'PCS',quantity:1,unit_price:0,discount:0,tax_rate:0})}
async function saveOrder(){if(!form.value.customer_id||!form.value.items.length){error.value='Select a customer and add at least one item.';return}try{const{data}=form.value.id?await client.put('/sales-orders/'+form.value.id,form.value):await client.post('/sales-orders',form.value);form.value=normalize(data.data);editing.value=false;await load();notice.value='Sales order saved.'}catch(e){error.value=apiError(e)}}async function workflow(action){try{const{data}=await client.post('/sales-orders/'+form.value.id+'/workflow',{action});form.value=normalize(data.data);await load();notice.value='Sales order '+form.value.status.toLowerCase()+'.'}catch(e){error.value=apiError(e)}}async function deleteOrder(){if(!confirm('Delete '+form.value.order_no+'?'))return;try{await client.delete('/sales-orders/'+form.value.id);await load();back()}catch(e){error.value=apiError(e)}}async function upload(e){const f=e.target.files[0];if(!f)return;const b=new FormData();b.append('file',f);try{const{data}=await client.post('/sales-orders/'+form.value.id+'/attachments',b);form.value=normalize(data.data)}catch(x){error.value=apiError(x)}finally{e.target.value=''}}async function downloadAttachment(f){const{data}=await client.get('/sales-orders/'+form.value.id+'/attachments/'+f.id,{responseType:'blob'});download(data,f.name)}function download(b,n){const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function details(v){try{return Object.entries(typeof v==='string'?JSON.parse(v):v||{}).map(([k,x])=>k+': '+x).join(', ')}catch{return''}}
function printPage(){window.print()}function emailOrder(){window.location.href='mailto:'+encodeURIComponent(customer.value.email||'')+'?subject='+encodeURIComponent('Sales Order '+(form.value.order_no||''))+'&body='+encodeURIComponent('Order total: '+form.value.currency_code+' '+money(total.value))}async function exportExcel(){const{default:ExcelJS}=await import('exceljs'),b=new ExcelJS.Workbook(),s=b.addWorksheet('Sales Orders');s.addRow(['Order No','Date','Customer','Customer PO','Salesperson','Currency','Total','Status']);filtered.value.forEach(x=>s.addRow([x.order_no,dateLabel(x.order_date),x.customer_details?.name,x.customer_po_no,x.salesperson,x.currency_code,Number(x.total),x.status]));s.columns.forEach(x=>x.width=22);download(new Blob([await b.xlsx.writeBuffer()]),'sales-orders.xlsx')}async function savePdf(){const{default:jsPDF}=await import('jspdf'),p=new jsPDF();p.setFontSize(18);p.text('Sales Order '+(form.value.order_no||''),15,18);p.setFontSize(10);p.text('Customer: '+(customer.value.name||'-'),15,30);let y=42;form.value.items.forEach(x=>{p.text([x.name,x.quantity+' '+x.uom,money(lineTotal(x))].join(' | '),15,y);y+=7});p.setFontSize(14);p.text('Grand Total: '+form.value.currency_code+' '+money(total.value),15,y+8);p.save((form.value.order_no||'sales-order')+'.pdf')}onMounted(async()=>{busy.value=true;try{await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}})
</script><style src="../assets/purchase-orders.css"></style>
